import SwiftUI
let termDescriptions=["Mặt Trời ở kinh độ 0°, ngày đêm gần bằng nhau.","Kinh độ 15°. Gắn với tục tảo mộ và tưởng nhớ tổ tiên.","Kinh độ 30°. Tên gọi gợi mưa thuận lợi cho cây trồng.","Kinh độ 45°. Mốc bắt đầu mùa hạ trong hệ tiết khí.","Kinh độ 60°. Tên gọi gợi hạt ngũ cốc bắt đầu đầy.","Kinh độ 75°. Gắn với mùa gieo cấy cây có hạt.","Kinh độ 90°. Ngày dài nhất ở Bắc bán cầu.","Kinh độ 105°. Gợi thời kỳ nóng đầu mùa.","Kinh độ 120°. Gợi thời kỳ nóng cao điểm.","Kinh độ 135°. Mốc bắt đầu mùa thu theo tiết khí.","Kinh độ 150°. Tên gọi gợi cái nóng dần rút.","Kinh độ 165°. Tên gọi gợi sương trắng.","Kinh độ 180°. Ngày đêm gần bằng nhau.","Kinh độ 195°. Tên gọi gợi sương lạnh.","Kinh độ 210°. Tên gọi gợi sương giá.","Kinh độ 225°. Mốc bắt đầu mùa đông theo tiết khí.","Kinh độ 240°. Tên gọi gợi tuyết nhẹ ở vùng lạnh.","Kinh độ 255°. Tên gọi gợi tuyết dày ở vùng lạnh.","Kinh độ 270°. Ngày ngắn nhất ở Bắc bán cầu.","Kinh độ 285°. Tên gọi gợi rét nhẹ.","Kinh độ 300°. Tên gọi gợi thời kỳ rét sâu.","Kinh độ 315°. Mốc bắt đầu mùa xuân theo tiết khí.","Kinh độ 330°. Tên gọi gợi nước mưa.","Kinh độ 345°. Tên gọi gợi côn trùng thức dậy sau mùa lạnh."]
struct TermView:View{let index:Int;var body:some View{ScrollView{VStack(alignment:.leading,spacing:16){Image("solar_"+LunarEngine.termAssets[index]).resizable().scaledToFit().frame(maxHeight:260);Text(LunarEngine.terms[index]).font(.largeTitle.bold()).foregroundStyle(red);Text(termDescriptions[index]);Text("Tiết khí được xác định theo kinh độ Mặt Trời, mỗi tiết cách nhau 15°. Ứng dụng tính theo thời điểm giữa ngày tại UTC+7; không phải dự báo thời tiết. Đặc điểm mùa thay đổi theo vùng miền Việt Nam.").foregroundStyle(.secondary);Text("Tiết tiếp theo: \(LunarEngine.terms[(index+1)%24])").font(.headline)}.padding()}.navigationTitle("Tiết khí").navigationBarTitleDisplayMode(.inline)}}
struct CultureView:View{let festivals=[("Tết Nguyên Đán","tet","Mùng 1 tháng Giêng âm lịch. Dịp đoàn viên, chúc Tết và tưởng nhớ tổ tiên."),("Rằm tháng Giêng","nguyen_tieu","Ngày 15 tháng Giêng, dịp lễ đầu năm."),("Thanh Minh","thanh_minh","Tiết khí gắn với tục tảo mộ."),("Giỗ Tổ Hùng Vương","gio_to","Mùng 10 tháng 3 âm lịch, tưởng nhớ các Vua Hùng."),("Đoan Ngọ","doan_ngo","Mùng 5 tháng 5 âm lịch, phong tục khác nhau theo vùng."),("Vu Lan","vu_lan","Rằm tháng 7, gắn với truyền thống báo hiếu."),("Trung Thu","trung_thu","Rằm tháng 8, dịp thưởng trăng và vui chơi của trẻ em."),("Ông Công Ông Táo","ong_tao","Ngày 23 tháng Chạp, tiễn Táo quân theo dân gian."),("Giao thừa","giao_thua","Thời khắc chuyển giao năm cũ sang năm mới."),("Mùng một và rằm","ram_mung_mot","Ngày đầu và giữa tháng âm lịch.")];var body:some View{List{Section("24 tiết khí"){ForEach(0..<24,id:\.self){i in NavigationLink{TermView(index:i)}label:{HStack{Image("solar_"+LunarEngine.termAssets[i]).resizable().scaledToFit().frame(width:56,height:52);Text(LunarEngine.terms[i])}}}};Section("Lễ hội Việt"){ForEach(festivals.indices,id:\.self){i in let f=festivals[i];NavigationLink{ScrollView{VStack(alignment:.leading,spacing:16){Image("festival_header_"+f.1).resizable().scaledToFit();Text(f.0).font(.title.bold());Text(f.2)}.padding()}.navigationTitle(f.0)}label:{Label(f.0,systemImage:"book")}}};Section("Tra cứu"){NavigationLink("12 con giáp"){ZodiacGallery(western:false)};NavigationLink("12 cung hoàng đạo"){ZodiacGallery(western:true)};NavigationLink("Thiên Can – Địa Chi"){CanChiView()}}}.navigationTitle("Văn hóa")}}
struct ZodiacGallery:View{let western:Bool;let names=["Bạch Dương","Kim Ngưu","Song Tử","Cự Giải","Sư Tử","Xử Nữ","Thiên Bình","Bọ Cạp","Nhân Mã","Ma Kết","Bảo Bình","Song Ngư"];let animals=["ty_rat","suu_buffalo","dan_tiger","mao_cat","thin_dragon","ty_snake","ngo_horse","mui_goat","than_monkey","dau_rooster","tuat_dog","hoi_pig"];let signs=["aries","taurus","gemini","cancer","leo","virgo","libra","scorpio","sagittarius","capricorn","aquarius","pisces"];let animalNames=["Chuột","Trâu","Hổ","Mèo","Rồng","Rắn","Ngựa","Dê","Khỉ","Gà","Chó","Lợn"];var body:some View{ScrollView{LazyVGrid(columns:[GridItem(.adaptive(minimum:105))]){ForEach(0..<12,id:\.self){i in Surface{VStack{Image(western ? "western_"+signs[i]:"animal_"+animals[i]).resizable().scaledToFit().frame(height:95);Text(western ? names[i]:LunarEngine.branches[i]).font(.headline);if !western{Text(animalNames[i]).font(.caption)}}.frame(maxWidth:.infinity)}}}.padding()}.navigationTitle(western ? "Cung hoàng đạo":"12 con giáp")}}
struct CanChiView:View{@State private var year=2026;var body:some View{Form{Stepper("Năm \(year)",value:$year,in:1900...2100);Text(LunarEngine.yearName(year)).font(.largeTitle.bold());Text("Can Chi ở đây tính theo năm âm lịch, chuyển năm vào Tết Nguyên Đán.").font(.caption);Section("10 Thiên Can"){ForEach(LunarEngine.stems,id:\.self){Text($0)}};Section("12 Địa Chi"){ForEach(LunarEngine.branches,id:\.self){Text($0)}}}.navigationTitle("Thiên Can – Địa Chi")}}
struct SettingsView:View{@EnvironmentObject var store:FamilyStore;var body:some View{List{Section("Tiện ích"){NavigationLink("Gia đình và ngày giỗ"){FamilyView()};NavigationLink("Đổi ngày âm dương"){ConvertView()};NavigationLink("Chủ đề lịch"){WidgetGallery()};Button("Cấp quyền nhắc việc"){Task{await store.enable()}}};Section("Ứng dụng"){Text("ViePN Lịch Việt 4.0 · Foundation");Text("Dữ liệu lưu cục bộ. Lịch tính theo UTC+7.");Text("Các quan niệm ngày tốt và giờ tốt chỉ mang tính tham khảo.").font(.caption)}}.navigationTitle("Cài đặt")}}
struct WidgetGallery:View{let themes=["peach","apricot","lotus","bamboo","ivory","night"];let labels=["Hoa đào","Hoa mai","Sen Việt","Tre xanh","Trắng ngà","Đêm trăng"];var body:some View{ScrollView{LazyVGrid(columns:[GridItem(.flexible()),GridItem(.flexible())]){ForEach(themes.indices,id:\.self){i in VStack{Image("widget_"+themes[i]+"_small").resizable().scaledToFit().clipShape(RoundedRectangle(cornerRadius:18));Text(labels[i]).font(.subheadline)}}}.padding();Text("Thư viện xem trước nền lịch. Bản ký cá nhân này không cài Widget Extension.").font(.caption).padding()}.navigationTitle("Chủ đề lịch")}}
